var _yamlSafeSchema = jsYaml["JSON_SCHEMA"];
function safeParseYaml(text) {
  return _yamlParse(text, { schema: _yamlSafeSchema });
}
var __dirname = path.dirname(fileURLToPath(import.meta.url));
var VALID_BRANCHES = ["main", "api-spec-design"];
var GITLAB_GROUP = "appliedsystems/products/epic/api-gateway/proxies";
var CACHE_DIR = process.env.EPIC_API_CATALOG_CACHE_DIR || path.join(__dirname, "..", "cache");
function catalogFilePath(branch) {
  return path.join(CACHE_DIR, `catalog-${branch}.json`);
}
function glabExec(apiPath) {
  return execFileSync("glab", ["api", apiPath], {
    encoding: "utf-8",
    timeout: 3e4
  });
}
function listProxyRepos() {
  const encoded = encodeURIComponent(GITLAB_GROUP);
  const raw = glabExec(`groups/${encoded}/projects?per_page=100`);
  const projects = JSON.parse(raw);
  return projects.map((p) => p.name).sort();
}
function listSpecFiles(repoName, branch) {
  const projectPath = `${GITLAB_GROUP}/${repoName}`;
  const encoded = encodeURIComponent(projectPath);
  try {
    const raw = glabExec(
      `projects/${encoded}/repository/tree?path=specs&ref=${branch}`
    );

